import * as THREE from 'three/webgpu';
import { texture, uv, vec4, mix, float, uniform, mx_noise_float } from 'three/tsl';
import { createTextMesh } from '@/text';

export default function createNode(config, ctx) {
  const group = new THREE.Group();
  group.name = 'hero-headline';
  group.position.set(0, 3, 0);
  group.rotation.set(0, 0, 0);
  group.scale.set(1, 1, 1);

  const width = 3.2;
  const height = 2.0;

  const geometry = new THREE.PlaneGeometry(width, height, 1, 1);

  const map = ctx.textureLoader.load('/prism-mock/home/nodes/feature-card.png');
  map.colorSpace = THREE.SRGBColorSpace;

  const grainStrength = uniform(0.035);
  const uvNode = uv();
  const texColor = texture(map, uvNode);

  const noise = mx_noise_float(uvNode.mul(512.0), float(1.0));
  const grain = noise.mul(grainStrength);

  const inkColor = vec4(0.086, 0.086, 0.114, 1.0);
  const gradientMix = uvNode.y.oneMinus().mul(0.35);
  const engineeredGradient = mix(texColor, inkColor, gradientMix);

  const finalColor = engineeredGradient.add(vec4(grain, grain, grain, 0.0));

  const material = new THREE.MeshBasicNodeMaterial({
    transparent: true,
  });
  material.colorNode = finalColor;

  const plane = new THREE.Mesh(geometry, material);
  plane.name = 'hero-headline-plane';
  group.add(plane);

  const textMesh = createTextMesh({
    text: 'A machined-metal watch atelier landing with catalog, pricing, jo',
    font: 'JetBrains Mono',
    weight: 400,
    sizeEm: 0.13,
    color: '#e8ecf2',
    maxWidth: width * 0.85,
    align: 'center',
    fontAtlas: ctx.fontAtlas,
  });
  textMesh.position.set(0, -height / 2 + 0.35, 0.01);
  textMesh.name = 'hero-headline-text';
  group.add(textMesh);

  group.userData.handlers = {};

  group.userData.cleanup = () => {
    geometry.dispose();
    material.dispose();
    if (map) map.dispose();
    if (textMesh.geometry) textMesh.geometry.dispose();
    if (textMesh.material) textMesh.material.dispose();
    if (textMesh.userData && typeof textMesh.userData.cleanup === 'function') {
      textMesh.userData.cleanup();
    }
  };

  return group;
}
